import { existsSync, readFileSync } from 'node:fs'
import { dirname, extname, join, normalize, sep } from 'node:path'
import type { UiAssets } from './handler'
import { cacheRoot, duckdbPlatform } from './platform'
import { unpackOnce } from './unpack'

/** What a compiled binary carries (generated by scripts/build-binary.ts). */
export interface Embedded {
  version: string
  duckdb: string
  platform: string
  buildId: string
  /** UI path (relative, forward slashes) → embedded file path. */
  ui: Record<string, string>
  /** Extension name → embedded gzipped file path. */
  extensions: Record<string, string>
}

export interface Runtime {
  version: string
  duckdb: string
  mode: 'binary' | 'development'
  ui?: UiAssets
  extensionPath(name: string): Promise<string>
}

const TYPES: Record<string, string> = {
  '.html': 'text/html; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.mjs': 'text/javascript; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.json': 'application/json',
  '.svg': 'image/svg+xml',
  '.png': 'image/png',
  '.ico': 'image/x-icon',
  '.woff2': 'font/woff2',
  '.woff': 'font/woff',
  '.wasm': 'application/wasm',
}

const typeOf = (path: string) => TYPES[extname(path).toLowerCase()] ?? 'application/octet-stream'

/** The UI's entry page is `standalone.html`; serve it for `index.html` too. */
const entryAliases = (path: string) => (path === 'index.html' ? ['index.html', 'standalone.html'] : [path])

function embeddedUi(files: Record<string, string>): UiAssets {
  return {
    async get(path) {
      for (const candidate of entryAliases(path)) {
        const file = files[candidate]
        if (file) return { body: readFileSync(file), type: typeOf(candidate) }
      }
      return null
    },
  }
}

function directoryUi(root: string): UiAssets {
  return {
    async get(path) {
      for (const candidate of entryAliases(path)) {
        const target = normalize(join(root, candidate))
        if (!target.startsWith(root + sep)) return null
        if (existsSync(target)) return { body: readFileSync(target), type: typeOf(target) }
      }
      return null
    },
  }
}

const here = dirname(new URL(import.meta.url).pathname.replace(/^\/([A-Za-z]:)/, '$1'))

function developmentRuntime(): Runtime {
  const cliRoot = join(here, '..')
  const manifest = JSON.parse(readFileSync(join(cliRoot, '..', '..', 'node_modules', '@duckdb', 'node-api', 'package.json'), 'utf8')) as { version: string }
  const duckdb = manifest.version.replace(/-.*$/, '')
  const version = (JSON.parse(readFileSync(join(cliRoot, 'package.json'), 'utf8')) as { version: string }).version
  const uiRoot = [join(cliRoot, '.build', 'ui'), join(cliRoot, '..', '..', 'python', 'src', 'sheetbase', 'static', 'app')]
    .find((dir) => existsSync(join(dir, 'standalone.html')) || existsSync(join(dir, 'index.html')))
  const extensionDir = process.env.SHEETBASE_DUCKDB_EXTENSIONS ?? join(cliRoot, '.cache', 'natives', `v${duckdb}`, duckdbPlatform(), 'extensions')
  return {
    version: `${version}-dev`,
    duckdb,
    mode: 'development',
    ui: uiRoot ? directoryUi(uiRoot) : undefined,
    async extensionPath(name) {
      const path = join(extensionDir, `${name}.duckdb_extension`)
      if (!existsSync(path)) throw new Error(`The ${name.replace(/_scanner$/, '')} connector isn't available: run \`bun run --filter sheetbase-studio-cli fetch:natives\`.`)
      return path
    },
  }
}

function binaryRuntime(embedded: Embedded): Runtime {
  const dir = join(cacheRoot(), embedded.buildId)
  return {
    version: embedded.version,
    duckdb: embedded.duckdb,
    mode: 'binary',
    ui: embeddedUi(embedded.ui),
    async extensionPath(name) {
      const source = embedded.extensions[name]
      if (!source) throw new Error(`The ${name.replace(/_scanner$/, '')} connector isn't in this build.`)
      return unpackOnce(source, join(dir, 'extensions', `${name}.duckdb_extension`))
    },
  }
}

/** The compiled binary's embedded files, or the repository when run from source. */
export async function loadRuntime(): Promise<Runtime> {
  try {
    const embedded = (await import('sheetbase:embedded')) as unknown as Embedded
    return binaryRuntime(embedded)
  } catch {
    return developmentRuntime()
  }
}
